style.css:
@-moz-document domain("hh.ru"), domain("hh.kz"), domain("hh.uz"), domain("hh.by"), domain("rabota.by"), domain("headhunter.kg") {
:root { color-scheme: dark !important; }

  /* ----------------------------------------------------------------------
     hh runs on the "Magritte" / "Bloko" design-token system: nearly every
     surface, text and stroke colour is a CSS custom property. Remapping the
     light tokens to dark equivalents reskins the whole UI at once; the
     element-level rules below back that up for the few spots painted directly
     and for the older legacy text colours.
     Tokens are version-suffixed (v21 / v24 / v0-12-2 for bloko), so the core
     ones are remapped for every live variant.
     --------------------------------------------------------------------- */
  html, body, body.magritte-hh-day-theme, :root {
    /* surfaces */
    --magritte-color-background-primary-v24-7-0: #14181d;
    --magritte-color-background-primary-v21-1-0: #14181d;
    --magritte-color-background-secondary-v24-7-0: #1c2128;
    --magritte-color-background-secondary-v21-1-0: #1c2128;
    --magritte-color-background-tertiary-v24-7-0: #21262d;
    --magritte-color-background-tertiary-v21-1-0: #21262d;
    /* primary text */
    --magritte-color-text-primary-v24-7-0: #e6edf3;
    --magritte-color-text-primary-v21-1-0: #e6edf3;
    /* secondary / tertiary text */
    --magritte-color-text-secondary-v24-7-0: #8b949e;
    --magritte-color-text-secondary-v21-1-0: #8b949e;
    --magritte-color-text-tertiary-v24-7-0: #6e7681;
    --magritte-color-text-tertiary-v21-1-0: #6e7681;
    /* accent text / links */
    --magritte-color-text-accent-v24-7-0: #5fb0e6;
    --magritte-color-text-accent-v21-1-0: #5fb0e6;
    --magritte-color-text-accent-secondary-v24-7-0: #5fb0e6;
    --magritte-color-text-accent-secondary-v21-1-0: #5fb0e6;
    --magritte-color-icon-accent-v24-7-0: #5fb0e6;
    --magritte-color-icon-accent-v21-1-0: #5fb0e6;
    /* strokes / borders */
    --magritte-color-stroke-neutral-v24-7-0: #2d333b;
    --magritte-color-stroke-neutral-v21-1-0: #2d333b;
    --magritte-color-stroke-neutral-heavy-v24-7-0: #3a424c;
    --magritte-color-stroke-neutral-heavy-v21-1-0: #3a424c;
    /* component surfaces (cards, inputs, dropdowns, modals, tooltips) */
    --magritte-color-component-card-background-primary-v24-7-0: #1c2128;
    --magritte-color-component-modal-background-content-v24-7-0: #1c2128;
    --magritte-color-component-drop-background-content-v24-7-0: #1c2128;
    --magritte-color-component-tag-background-on-surface-neutral-v24-7-0: #21262d;
    --magritte-color-component-input-background-field-v24-7-0: #1c2128;
    --magritte-color-component-input-background-state-field-hovered-v24-7-0: #1c2128;
    --magritte-color-component-input-background-state-field-focused-v24-7-0: #1c2128;
    --magritte-color-component-input-background-state-field-invalid-v24-7-0: #1c2128;
    --magritte-color-component-input-background-state-field-disabled-v24-7-0: #181d23;
    --magritte-color-component-tooltip-background-content-v21-1-0: #21262d;
    --magritte-color-component-tooltip-background-content-v24-7-0: #21262d;
    /* legacy bloko */
    --bloko-color-special-tertiary: #8b949e;
    --bloko-color-special-secondary: #c4cdd6;

    /* --- Magritte v24-7-2 (current live suffix) ---------------------------
       hh bumped the whole token set to a new version suffix; the v24-7-0 names
       above now resolve on only a handful of components, so the same core
       tokens must be remapped again under the new suffix. Without this the
       icons render #000 on dark, drops/inputs paint #fff, and every button
       falls back to its light surface. */
    /* surfaces */
    --magritte-color-background-primary-v24-7-2: #14181d;
    --magritte-color-background-body-v24-7-2: #14181d;
    --magritte-color-background-secondary-v24-7-2: #1c2128;
    --magritte-color-background-tertiary-v24-7-2: #21262d;
    --magritte-color-background-state-primary-hovered-v24-7-2: #14181d;
    --magritte-color-background-state-primary-pressed-v24-7-2: #14181d;
    --magritte-color-background-state-secondary-hovered-v24-7-2: #21262d;
    --magritte-color-background-state-secondary-pressed-v24-7-2: #2d333b;
    --magritte-color-background-state-tertiary-hovered-v24-7-2: #2d333b;
    --magritte-color-background-state-tertiary-pressed-v24-7-2: #2d333b;
    /* tinted "secondary" surfaces (badge / callout backdrops) */
    --magritte-color-background-accent-secondary-v24-7-2: #1f3550;
    --magritte-color-background-positive-secondary-v24-7-2: #16301f;
    --magritte-color-background-negative-secondary-v24-7-2: #3a231e;
    --magritte-color-background-warning-secondary-v24-7-2: #33261a;
    --magritte-color-background-special-secondary-v24-7-2: #241d33;
    --magritte-color-background-dreamy-secondary-v24-7-2: #16303c;
    --magritte-color-background-lovely-secondary-v24-7-2: #3a1c24;
    --magritte-color-background-vivid-secondary-v24-7-2: #332c14;
    /* text */
    --magritte-color-text-primary-v24-7-2: #e6edf3;
    --magritte-color-text-secondary-v24-7-2: #8b949e;
    --magritte-color-text-dense-v24-7-2: #c4cdd6;
    --magritte-color-text-accent-v24-7-2: #5fb0e6;
    --magritte-color-text-accent-secondary-v24-7-2: #5fb0e6;
    --magritte-color-text-state-primary-hovered-v24-7-2: #ffffff;
    --magritte-color-text-state-primary-pressed-v24-7-2: #e6edf3;
    /* icons — icon-primary shipped #000: black glyphs on every dark surface */
    --magritte-color-icon-primary-v24-7-2: #c4cdd6;
    --magritte-color-icon-secondary-v24-7-2: #8b949e;
    --magritte-color-icon-accent-v24-7-2: #5fb0e6;
    --magritte-color-icon-accent-secondary-v24-7-2: #5fb0e6;
    --magritte-color-icon-state-primary-hovered-v24-7-2: #e6edf3;
    --magritte-color-icon-state-primary-pressed-v24-7-2: #ffffff;
    --magritte-color-icon-state-secondary-hovered-v24-7-2: #c4cdd6;
    /* strokes */
    --magritte-color-stroke-neutral-v24-7-2: #2d333b;
    --magritte-color-stroke-neutral-heavy-v24-7-2: #3a424c;
    --magritte-color-stroke-phantom-v24-7-2: #2d333b;
    --magritte-color-stroke-state-neutral-hovered-v24-7-2: #3a424c;
    --magritte-color-stroke-state-neutral-pressed-v24-7-2: #3a424c;
    /* floating surfaces */
    --magritte-color-component-drop-background-content-v24-7-2: #1c2128;
    --magritte-color-component-modal-background-content-v24-7-2: #1c2128;
    /* inputs */
    --magritte-color-component-input-background-field-v24-7-2: #1c2128;
    --magritte-color-component-input-background-state-field-hovered-v24-7-2: #1c2128;
    --magritte-color-component-input-background-state-field-focused-v24-7-2: #1c2128;
    --magritte-color-component-input-background-state-field-invalid-v24-7-2: #1c2128;
    --magritte-color-component-input-background-state-field-disabled-v24-7-2: #181d23;
    --magritte-color-component-input-text-content-v24-7-2: #e6edf3;
    --magritte-color-component-input-text-label-v24-7-2: #8b949e;
    --magritte-color-component-input-text-placeholder-v24-7-2: #8b949e;
    --magritte-color-component-input-text-postfix-v24-7-2: #8b949e;
    --magritte-color-component-input-icon-content-v24-7-2: #8b949e;
    --magritte-color-component-input-stroke-field-v24-7-2: #2d333b;
    /* buttons: the surface now lives on an inner "-view" span fed by these */
    --magritte-color-component-button-background-neutral-v24-7-2: #30363d;
    --magritte-color-component-button-background-neutral-secondary-v24-7-2: #21262d;
    --magritte-color-component-button-background-accent-v24-7-2: #2f81f7;
    --magritte-color-component-button-background-accent-secondary-v24-7-2: #1f3550;
    --magritte-color-component-button-background-state-neutral-hovered-v24-7-2: #3a424c;
    --magritte-color-component-button-background-state-neutral-pressed-v24-7-2: #3a424c;
    --magritte-color-component-button-background-state-neutral-secondary-hovered-v24-7-2: #2d333b;
    --magritte-color-component-button-background-state-neutral-secondary-pressed-v24-7-2: #2d333b;
    --magritte-color-component-button-background-state-accent-hovered-v24-7-2: #4c9bff;
    --magritte-color-component-button-background-state-accent-pressed-v24-7-2: #4c9bff;
    --magritte-color-component-button-background-state-accent-secondary-hovered-v24-7-2: #24406040;
    --magritte-color-component-button-text-neutral-secondary-v24-7-2: #e6edf3;
    --magritte-color-component-button-text-neutral-tertiary-v24-7-2: #c4cdd6;
    --magritte-color-component-button-text-accent-secondary-v24-7-2: #5fb0e6;
    --magritte-color-component-button-text-accent-tertiary-v24-7-2: #5fb0e6;
    --magritte-color-component-button-icon-neutral-secondary-v24-7-2: #e6edf3;
    --magritte-color-component-button-icon-neutral-tertiary-v24-7-2: #c4cdd6;
    --magritte-color-component-button-icon-accent-secondary-v24-7-2: #5fb0e6;
    --magritte-color-component-button-icon-accent-tertiary-v24-7-2: #5fb0e6;
    /* tags / chips */
    --magritte-color-component-tag-background-neutral-v24-7-2: #21262d;
    --magritte-color-component-tag-background-accent-v24-7-2: #1f3550;
    --magritte-color-component-tag-background-positive-v24-7-2: #16301f;
    --magritte-color-component-tag-background-negative-v24-7-2: #3a231e;
    --magritte-color-component-tag-background-warning-v24-7-2: #33261a;
    --magritte-color-component-tag-background-special-v24-7-2: #241d33;
    --magritte-color-component-tag-background-on-surface-neutral-v24-7-2: #21262d;
    --magritte-color-component-tag-background-on-surface-accent-v24-7-2: #1f3550;
    --magritte-color-component-tag-background-on-surface-positive-v24-7-2: #16301f;
    --magritte-color-component-tag-background-on-surface-negative-v24-7-2: #3a231e;
    --magritte-color-component-tag-background-on-surface-warning-v24-7-2: #33261a;
    --magritte-color-component-tag-background-on-surface-special-v24-7-2: #241d33;
    /* chips (filter chips + the removable "Москва ✕" tag): own token family,
       all light, incl. a #000 icon token that paints the ✕ / + glyph black */
    --magritte-color-component-chips-background-unchecked-neutral-v24-7-2: #21262d;
    --magritte-color-component-chips-background-unchecked-neutral-secondary-v24-7-2: #21262d;
    --magritte-color-component-chips-background-unchecked-accent-v24-7-2: #1f3550;
    --magritte-color-component-chips-background-checked-neutral-v24-7-2: #1f3550;
    --magritte-color-component-chips-background-checked-neutral-secondary-v24-7-2: #21262d;
    --magritte-color-component-chips-background-checked-accent-v24-7-2: #2f81f7;
    --magritte-color-component-chips-background-state-unchecked-neutral-hovered-v24-7-2: #2d333b;
    --magritte-color-component-chips-background-state-unchecked-neutral-secondary-hovered-v24-7-2: #2d333b;
    --magritte-color-component-chips-background-state-unchecked-accent-hovered-v24-7-2: #24406b;
    --magritte-color-component-chips-background-state-checked-neutral-hovered-v24-7-2: #24406b;
    --magritte-color-component-chips-background-state-checked-neutral-secondary-hovered-v24-7-2: #2d333b;
    --magritte-color-component-chips-text-unchecked-neutral-v24-7-2: #c4cdd6;
    --magritte-color-component-chips-text-unchecked-neutral-secondary-v24-7-2: #c4cdd6;
    --magritte-color-component-chips-text-unchecked-accent-v24-7-2: #5fb0e6;
    --magritte-color-component-chips-text-checked-neutral-secondary-v24-7-2: #e6edf3;
    --magritte-color-component-chips-text-state-unchecked-neutral-hovered-v24-7-2: #e6edf3;
    --magritte-color-component-chips-text-state-unchecked-neutral-secondary-hovered-v24-7-2: #e6edf3;
    --magritte-color-component-chips-text-state-checked-neutral-secondary-hovered-v24-7-2: #e6edf3;
    --magritte-color-component-chips-text-state-unchecked-accent-hovered-v24-7-2: #9bd4ff;
    --magritte-color-component-chips-icon-unchecked-neutral-v24-7-2: #c4cdd6;
    --magritte-color-component-chips-icon-unchecked-accent-v24-7-2: #5fb0e6;
    --magritte-color-component-chips-icon-checked-neutral-secondary-v24-7-2: #e6edf3;
    --magritte-color-component-chips-icon-state-unchecked-neutral-hovered-v24-7-2: #e6edf3;
    --magritte-color-component-chips-icon-state-checked-neutral-secondary-hovered-v24-7-2: #e6edf3;
    --magritte-color-component-chips-icon-state-unchecked-accent-hovered-v24-7-2: #9bd4ff;
    --magritte-color-component-chips-stroke-unchecked-neutral-secondary-v24-7-2: #2d333b;
    --magritte-color-component-chips-stroke-checked-neutral-secondary-v24-7-2: #3a424c;
    --magritte-color-component-chips-stroke-state-unchecked-neutral-secondary-hovered-v24-7-2: #3a424c;
    --magritte-color-component-chips-stroke-state-checked-neutral-secondary-hovered-v24-7-2: #3a424c;
    /* checkboxes / radios / selectable cards */
    --magritte-color-component-checkable-background-unchecked-v24-7-2: #1c2128;
    --magritte-color-component-checkable-background-state-unchecked-hovered-v24-7-2: #21262d;
    --magritte-color-component-checkable-background-checked-v24-7-2: #2f81f7;
    --magritte-color-component-checkable-stroke-unchecked-v24-7-2: #3a424c;
    --magritte-color-component-checkable-stroke-state-unchecked-hovered-v24-7-2: #4a545f;
    --magritte-color-component-checkable-icon-state-unchecked-hovered-v24-7-2: #2d333b;
    --magritte-color-component-checkable-card-background-unchecked-v24-7-2: #1c2128;
    --magritte-color-component-checkable-card-background-state-unchecked-hovered-v24-7-2: #21262d;
    --magritte-color-component-checkable-card-background-state-unchecked-tone-hovered-v24-7-2: #21262d;
    --magritte-color-component-checkable-card-background-state-checked-hovered-v24-7-2: #21262d;
    --magritte-color-component-checkable-card-background-state-checked-tone-hovered-v24-7-2: #21262d;
    --magritte-color-component-checkable-card-stroke-unchecked-v24-7-2: #2d333b;
    --magritte-color-component-checkable-card-stroke-state-unchecked-hovered-v24-7-2: #3a424c;
    /* segmented control ("Ищу работу" / "Ищу сотрудника") */
    --magritte-color-component-segmented-background-content-v24-7-2: #1c2128;
    --magritte-color-component-segmented-stroke-content-v24-7-2: #2d333b;
    --magritte-color-component-segmented-item-background-selected-v24-7-2: #30363d;
    --magritte-color-component-segmented-item-background-state-unselected-hovered-v24-7-2: #2d333b;
    --magritte-color-component-segmented-item-text-selected-v24-7-2: #e6edf3;
    --magritte-color-component-segmented-item-text-unselected-v24-7-2: #8b949e;
    --magritte-color-component-segmented-item-text-state-unselected-hovered-v24-7-2: #c4cdd6;
    --magritte-color-component-segmented-item-icon-selected-v24-7-2: #e6edf3;
    --magritte-color-component-segmented-item-icon-unselected-v24-7-2: #8b949e;
    --magritte-color-component-segmented-item-icon-state-unselected-hovered-v24-7-2: #c4cdd6;
    /* switches: keep the white knob, dark the off-track */
    --magritte-color-component-switch-background-container-unchecked-v24-7-2: #3a424c;
    --magritte-color-component-switch-background-state-container-unchecked-hovered-v24-7-2: #4a545f;

    /* --- Magritte v24-7-3 (newest live suffix) -------------------------------
       hh bumped the whole token set to a NEW version suffix again; the button
       component already consumes v24-7-3 (every secondary/accent/neutral button
       fell back to its light #f1f4f9 / #edf6ff surface), and the remaining
       components migrate progressively. Re-declare the same dark values under the
       new suffix so buttons darken now and nothing regresses as the rest moves. */
    --magritte-color-background-primary-v24-7-3: #14181d;
    --magritte-color-background-body-v24-7-3: #14181d;
    --magritte-color-background-secondary-v24-7-3: #1c2128;
    --magritte-color-background-tertiary-v24-7-3: #21262d;
    --magritte-color-background-state-primary-hovered-v24-7-3: #14181d;
    --magritte-color-background-state-primary-pressed-v24-7-3: #14181d;
    --magritte-color-background-state-secondary-hovered-v24-7-3: #21262d;
    --magritte-color-background-state-secondary-pressed-v24-7-3: #2d333b;
    --magritte-color-background-state-tertiary-hovered-v24-7-3: #2d333b;
    --magritte-color-background-state-tertiary-pressed-v24-7-3: #2d333b;
    --magritte-color-background-accent-secondary-v24-7-3: #1f3550;
    --magritte-color-background-positive-secondary-v24-7-3: #16301f;
    --magritte-color-background-negative-secondary-v24-7-3: #3a231e;
    --magritte-color-background-warning-secondary-v24-7-3: #33261a;
    --magritte-color-background-special-secondary-v24-7-3: #241d33;
    --magritte-color-background-dreamy-secondary-v24-7-3: #16303c;
    --magritte-color-background-lovely-secondary-v24-7-3: #3a1c24;
    --magritte-color-background-vivid-secondary-v24-7-3: #332c14;
    --magritte-color-text-primary-v24-7-3: #e6edf3;
    --magritte-color-text-secondary-v24-7-3: #8b949e;
    --magritte-color-text-dense-v24-7-3: #c4cdd6;
    --magritte-color-text-accent-v24-7-3: #5fb0e6;
    --magritte-color-text-accent-secondary-v24-7-3: #5fb0e6;
    --magritte-color-text-state-primary-hovered-v24-7-3: #ffffff;
    --magritte-color-text-state-primary-pressed-v24-7-3: #e6edf3;
    --magritte-color-icon-primary-v24-7-3: #c4cdd6;
    --magritte-color-icon-secondary-v24-7-3: #8b949e;
    --magritte-color-icon-accent-v24-7-3: #5fb0e6;
    --magritte-color-icon-accent-secondary-v24-7-3: #5fb0e6;
    --magritte-color-icon-state-primary-hovered-v24-7-3: #e6edf3;
    --magritte-color-icon-state-primary-pressed-v24-7-3: #ffffff;
    --magritte-color-icon-state-secondary-hovered-v24-7-3: #c4cdd6;
    --magritte-color-stroke-neutral-v24-7-3: #2d333b;
    --magritte-color-stroke-neutral-heavy-v24-7-3: #3a424c;
    --magritte-color-stroke-phantom-v24-7-3: #2d333b;
    --magritte-color-stroke-state-neutral-hovered-v24-7-3: #3a424c;
    --magritte-color-stroke-state-neutral-pressed-v24-7-3: #3a424c;
    --magritte-color-component-drop-background-content-v24-7-3: #1c2128;
    --magritte-color-component-modal-background-content-v24-7-3: #1c2128;
    --magritte-color-component-input-background-field-v24-7-3: #1c2128;
    --magritte-color-component-input-background-state-field-hovered-v24-7-3: #1c2128;
    --magritte-color-component-input-background-state-field-focused-v24-7-3: #1c2128;
    --magritte-color-component-input-background-state-field-invalid-v24-7-3: #1c2128;
    --magritte-color-component-input-background-state-field-disabled-v24-7-3: #181d23;
    --magritte-color-component-input-text-content-v24-7-3: #e6edf3;
    --magritte-color-component-input-text-label-v24-7-3: #8b949e;
    --magritte-color-component-input-text-placeholder-v24-7-3: #8b949e;
    --magritte-color-component-input-text-postfix-v24-7-3: #8b949e;
    --magritte-color-component-input-icon-content-v24-7-3: #8b949e;
    --magritte-color-component-input-stroke-field-v24-7-3: #2d333b;
    --magritte-color-component-button-background-neutral-v24-7-3: #30363d;
    --magritte-color-component-button-background-neutral-secondary-v24-7-3: #21262d;
    --magritte-color-component-button-background-accent-v24-7-3: #2f81f7;
    --magritte-color-component-button-background-accent-secondary-v24-7-3: #1f3550;
    --magritte-color-component-button-background-state-neutral-hovered-v24-7-3: #3a424c;
    --magritte-color-component-button-background-state-neutral-pressed-v24-7-3: #3a424c;
