  /* ---- Base surfaces ---- */
  html, body { background-color: #14181d !important; color: #c4cdd6 !important; }
  #HH-React-Root, #a11y-root, .HH-Supernova-MainContent, .main-content,
  [data-qa="main-content"], .supernova-content, .HH-MainContent-Wrapper,
  .bloko-column, [class*="layout"], [class*="content-wrapper"],
  [class*="magritte-page"], main {
    background-color: transparent !important; }

  /* ---- Soften all default light borders ---- */
  * { border-color: #2d333b !important; }

  /* ---- Header / global nav (supernova) ---- */
  .supernova-navi, .supernova-navi-wrapper, .supernova-navi-container,
  .supernova-navi-wrapper_theme-desktop-light, [class*="supernova-navi-wrapper"],
  .HH-Supernova-Header, .supernova-search-wrapper {
    background-color: #0d1117 !important; border-color: #2d333b !important; }
  .supernova-navi { border-bottom: 2px solid #c33c4a !important; } /* hh red, toned for dark */
  .supernova-navi a, .supernova-navi-item, .supernova-link,
  [data-qa^="mainmenu_"], [data-qa="allServices-button"], [data-qa="help-button"],
  [data-qa="moreItems-button"], [data-qa="geoSwitcher-button"],
  .supernova-navi-item-inner, .supernova-dropdown-anchor {
    color: #e6edf3 !important; }
  .supernova-navi a:hover, .supernova-navi-item:hover { color: #ffffff !important; }
  .supernova-dropdown, .supernova-dropdown-section, .supernova-dropdown-list,
  [class*="supernova-dropdown"], .supernova-overlay {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  /* The header role menu ("Ищу работу" / "Ищу сотрудника") is portaled into a
     legacy `bloko-drop_theme-light` panel that keeps a hardcoded WHITE surface.
     The dark supernova sections paint over most of it, so on desktop it hides —
     but at 390px the panel goes full-height and its white shows through the
     arrow notch above the menu. Its section divider is a light ::after strip
     (#eef1f7), invisible to an element-bg scan. Dark both. */
  .bloko-drop, [class*="bloko-drop"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .supernova-dropdown-section::after, .supernova-dropdown-section::before {
    background-color: #2d333b !important; }
  /* the menu's pointer is a pure-CSS triangle: a zero-size ::after whose
     border-bottom-color IS the arrow. The blanket `* { border-color }` never
     reaches a pseudo-element, so it stayed white above the dark menu. */
  .supernova-dropdown-arrow::after {
    border-bottom-color: #1c2128 !important; }
  .supernova-dropdown-arrow::before {
    border-bottom-color: #2d333b !important; }
  /* logo: keep its own colours, never tint the image */
  [data-qa="supernova-logo"], [data-qa="supernova-logo"] * { color: inherit; }

  /* ---- Generic Magritte cards / surfaces (hashed suffix → prefix match) ---- */
  [class*="magritte-card"], [class*="magritte-paper"],
  [class*="magritte-segments-container"], [class*="magritte-segment"],
  [class*="magritte-position-container"],
  [data-qa="vacancy-item-desktop"], [data-qa="company-item-desktop"],
  [data-qa="remote-item-desktop"], [data-qa="professions-item-desktop"],
  [data-qa="vacancy-serp__vacancy"], [class*="vacancy-card"],
  [class*="serp-item"], [class*="-card-"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [class*="magritte-card-style-special"],
  [class*="magritte-card-style-secondary"],
  [class*="magritte-segment"][class*="selected"] {
    background-color: #21262d !important; }
  [class*="magritte-card"]:hover, [data-qa="vacancy-serp__vacancy"]:hover {
    background-color: #21262d !important; }

  /* ---- Employer "chameleon" branded templates ---- */
  /* Two naming conventions ship in the wild: the hyphen family (tmpl-hh-*) and an
     UNDERSCORE family (tmpl_hh_*, e.g. the Газпромбанк page: tmpl_hh_wrapper /
     _appeal / _become-part cards ship a light-blue #eaf9ff shell + pure-white
     award cards). Both must be darkened — otherwise our forced light body text
     reads light-on-light-blue (unreadable). Cover both spellings. */
  [class*="tmpl-hh-wrapper"], [class*="tmpl-hh-facts"], [class*="tmpl-hh-banner"],
  [class*="tmpl-hh-offers"], [class*="tmpl-hh-find"], [class*="tmpl-hh-reviews"],
  [class*="tmpl-hh"], [class*="tmpl_hh"],
  [class*="with-top-image"], [class*="employer-tabs-wrapper"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [class*="tmpl-hh"] *, [class*="tmpl_hh"] * { color: #c4cdd6 !important; }
  [class*="tmpl-hh"] h1, [class*="tmpl-hh"] h2, [class*="tmpl-hh"] h3,
  [class*="tmpl_hh"] h1, [class*="tmpl_hh"] h2, [class*="tmpl_hh"] h3 { color: #e6edf3 !important; }
  /* Chameleon templates ship their own CTA button (`tmpl-hh-footer__link`): the
     employer's brand colour as a solid fill, declared in the vacancy's INLINE
     employer stylesheet (here `background: rgb(255,0,2)` + a white label). The
     blanket background rule above painted that fill the card colour and the
     global `* { border-color }` erased its matching border, so the CTA rendered
     as a near-invisible ghost outline on the dark card — a lost control, not just
     a lost hue (audit-chroma: bg rgb(253,0,2) → rgb(28,33,40)).
     The employer's own colour can't be recovered (our !important already replaced
     it) and employer CSS is unbounded — the same reason the text colours above are
     deliberately flattened — so give the CTA the theme's accent surface instead:
     it reads unmistakably as a button and its contrast holds on ANY employer page.
     The brand hue is knowingly traded for that guarantee.
     Scoped to `footer__link` — the filled CTA verified live — and NOT to a bare
     `__link`: the blanket already paints every chameleon anchor a card-coloured
     (invisible) slab, so widening this to all `__link`s would stamp a bright blue
     box around any employer's plain TEXT link on a template we cannot inspect.
     CTAs in other chameleon blocks stay flattened (unchanged, not a regression). */
  a[class*="tmpl-hh"][class*="footer__link"],
  a[class*="tmpl_hh"][class*="footer__link"] {
    background-color: #2f81f7 !important; border-color: #2f81f7 !important; }
  /* the CTA's own label/icon spans carry `tmpl-hh-*` classes too, so the blanket
     painted each of them a card-coloured slab — a dark box stamped across the
     button once the button itself is no longer that same colour. Clear them. */
  a[class*="tmpl-hh"][class*="footer__link"] *,
  a[class*="tmpl_hh"][class*="footer__link"] * {
    background-color: transparent !important; }
  a[class*="tmpl-hh"][class*="footer__link"],
  a[class*="tmpl_hh"][class*="footer__link"],
  a[class*="tmpl-hh"][class*="footer__link"] *,
  a[class*="tmpl_hh"][class*="footer__link"] * {
    color: #ffffff !important; }
  /* The chameleon CONTENT block (tmpl_hh_content) carries the vacancy's HTML body
     text, but the employer also paints it with an uploaded background-IMAGE — a
     near-white decorative JPG (e.g. img.hhcdn.ru/ichameleon/*.jpg). background-image
     paints OVER our background-color, so the surface stays white while our forced
     light body text sits on top → light-on-white, unreadable (only the left edge,
     where the JPG fades dark, stays legible). A bg-COLOR scan reads #1c2128 and is
     blind to it. Drop the image on the text block ONLY so our dark surface shows and
     the light text reads; the decorative head banner / footer slider keep their
     images (those JPGs are dark with baked-in white text and read fine). */
  [class*="tmpl_hh_content"], [class*="tmpl-hh-content"] {
    background-image: none !important; }
  /* hh's "chameleon" template-builder section widgets (the "Наша миссия" mission
     block and the "projects" block, reused across employers who build a page with
     hh's constructor) paint a full-panel LIGHT ::before (#f2f3f7) behind the whole
     section. The blanket tmpl_hh background rule only darkens the element's own
     background, never a pseudo — so the section band stayed near-white and our
     forced light body text read light-on-white (the heading + subtitle barely
     legible). A bg-COLOR element scan is blind to it. Dark the panel to the page
     base so the dark value cards on top read as elevated and the text reads. */
  [class*="tmpl_hh_mission"]::before, [class*="tmpl_hh_projects"]::before {
    background-color: #14181d !important; }
  /* newer Magritte "constructor" employer pages: the "О компании" body widget
     ships a hardcoded WHITE panel — our light body text then reads light-on-light
     (unreadable). Dark the widget surface; its text already maps to light grey. */
  [class*="employer-constructor-widget"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  /* the chameleon employer nav bar (tmpl_hh_navigation) is a swiper of section
     links; each link's chevron button is a bare <span> (no class, direct child of
     the <li>) with a hardcoded LIGHT #e2e5eb square — the blanket tmpl_hh rule
     darkens the <li>/<a> but never reaches this class-less span, so three bright
     40px squares glare on the dark page (the current-section item ships #000, fine).
     It's audit-blind at the surface floor (32px) — smallLight caught it. Dark the
     square to the theme's neutral button surface; its chevron is an external
     hhcdn.ru/ichameleon SVG (#626C77 grey on links, white on the current item) that
     we can't recolour, but both read on the dark square. */
  li[class*="tmpl_hh_navigation__item"] > span {
    background-color: #21262d !important; }
  /* Employers highlight phrases inside chameleon blocks with a bare, class-LESS
     inline tag carrying a pale fill from the employer's own stylesheet (e.g. the
     `tmpl-hh-footer__work-item__text > span` "well-being-программа" pills at
     #f0f0ff). The blanket `[class*="tmpl-hh"]` surface rule only reaches tags that
     CARRY a tmpl class, so these keep the pale fill while our forced light body
     text sits on top → light-on-white, unreadable. Same class as the highlight
     fills already neutralised inside `vacancy-branded-user-content`; clear them
     the same way. `:not([class])` keeps this to the bare inline tags, so every
     tmpl-classed span (captions/headings whose dark box carries their own text
     over a photo) and the navigation chevron square above are untouched. */
  [class*="tmpl-hh"] span:not([class]), [class*="tmpl_hh"] span:not([class]),
  [class*="tmpl-hh"] strong:not([class]), [class*="tmpl_hh"] strong:not([class]),
  [class*="tmpl-hh"] b:not([class]), [class*="tmpl_hh"] b:not([class]),
  [class*="tmpl-hh"] em:not([class]), [class*="tmpl_hh"] em:not([class]) {
    background-color: transparent !important; }
  /* SERP "branded snippet" promo cards ship the employer's OWN brand colour as an
     INLINE background-color on the outer wrapper (e.g. a light-blue #deeaff). The
     inner content is a dark magritte-card, but the wrapper's frame + the wide
     right-hand illustration column then glare light — a bright panel on the dark
     results list. It's audit-blind-ish (rotates per employer, inline non-white).
     Dark the wrapper so the frame + illustration column read dark; the decorative
     PNG (transparent) sits on dark like the rest of the card.
     Newer branded snippets ship the brand colour as a saturated linear-gradient
     background-IMAGE on the wrapper (e.g. a bright green rgb(13,108,11) promo),
     which paints OVER our background-color → the green frame glares around the
     dark inner card, and a bg-COLOR scan is blind to it. Drop the image too so the
     wrapper reads the same dark as the inline-colour variant; the ONLY match is the
     base wrapper (child `branded-snippet-picture--`/`-logo--` never contain the
     double-dash), so the decorative illustration + logo stay untouched. */
  [class*="branded-snippet--"] {
    background-color: #1c2128 !important; background-image: none !important; }

  /* ---- Typography ---- */
  h1, h2, h3, h4, h5, h6, [class*="magritte-title"], [class*="magritte-text"][class*="primary"],
  [data-qa="title"], [data-qa$="-title"], [data-qa="company-header-title-name"],
  [data-qa="bloko-header-1"], [data-qa="bloko-header-2"], [data-qa="bloko-header-3"] {
    color: #e6edf3 !important; }
  p, li, span:not(.metro-point), dd, dt, td, th, label, figcaption, time, small, b, strong, em,
  div, [class*="magritte-text"] {
    color: #c4cdd6 !important; }
  /* metro-line dots in vacancy addresses: an empty <span class="metro-point">
     whose inline `color:#<line>` paints a ::before "●" in the Moscow/SPb metro
     line colour. The blanket span rule above flattened every dot to grey,
     erasing the line coding; excluding it lets the inline colour win. */
  /* secondary / muted text used widely (#768694, #6a7885, #aabbca, #1b1b1b legacy) */
  [class*="secondary"], [class*="muted"], [data-qa$="-secondary"],
  [data-qa="vacancy-serp__vacancy-address"], [data-qa="vacancy-label-remote"],
  .bloko-text_tertiary, .supernova-navi-search-text {
    color: #8b949e !important; }

  /* ---- Links: hh blue is too dark on dark → readable blue ----
     A link's LABEL is almost always an inner <span> (magritte-text___), not a
     text node on the <a>. Two of our own rules outrank a plain `a span` (0-0-2)
     on it: the blanket `[class*="magritte-text"]` (0-1-0) and `span:not(.metro-point)`
     (0-1-1 — the :not() raised it). So every span-labelled link rendered body-grey:
     the whole "Работа по профессиям" grid, the footer legal links, "Я ищу
     сотрудника" — indistinguishable from prose, with no link affordance left.
     Match the blanket's shape so the link arm wins on the span too. Every rule
     below that must still beat this one (nav items, button labels, card titles)
     carries the same `:not(.metro-point)` to clear 0-1-2. */
  a, a span:not(.metro-point), .bloko-link, [class*="magritte-link"], [data-qa$="-link"] {
    color: #5fb0e6 !important; }
  a:hover, .bloko-link:hover, [class*="magritte-link"]:hover { color: #9bd4ff !important; }
  /* `magritte-link` is a BUTTON component (the "Развернуть" section expander, inline
     action links), so the `a span:not(.metro-point)` arm above never reaches its
     label — the innermost `magritte-text` span kept the blanket body-grey and the
     accent link read as plain prose, its clickable affordance gone (chroma: native
     #0070ff → grey). Colour the ACCENT variant's own text/icon spans blue; the
     NEUTRAL variant (the bulk — footer/nav links) is deliberately primary/grey and
     stays untouched.
     Both arms are compounded with `magritte-link___` (the component's own base
     class, on the same element) to reach 0-3-1: an expander rendered INSIDE a
     `magritte-text_style-secondary` block — the home "Работа в России" one — is
     also matched by the muted rule below at 0-2-1, which comes later in the file
     and would otherwise win, greying that one link while its siblings stay blue. */
  [class*="magritte-link___"][class*="magritte-link_style_accent"] span:not(.metro-point),
  [class*="magritte-link___"][class*="magritte-link_style_accent"] [class*="magritte-text"]:not(.metro-point) {
    color: #5fb0e6 !important; }
  /* Magritte marks muted metadata with `magritte-text_style-secondary`, but the
     rendered words often live in a bare class-LESS child span. Inside an <a> the
     link arm above (0-1-2) outranks the muted rule (0-1-0) on that span, so a
     tile whose whole body is a link came out with a BLUE "40140 вакансий" beside
     three identical grey siblings, and the SERP card's "Без опыта работы" turned
     link-blue too (native #768694 in both). Keep the site's muted grey. */
  [class*="magritte-text_style-secondary"] span:not(.metro-point) {
    color: #8b949e !important; }
  /* header nav items are anchors whose label is a span: they must stay primary
     text, not turn link-blue */
  .supernova-navi a span:not(.metro-point),
  .supernova-navi-item span:not(.metro-point) {
    color: #e6edf3 !important; }
  /* card/headline links should read as bright primary text, blue on hover */
  [data-qa="serp-item__title"], [data-qa="serp-item__title-text"],
  [data-qa="vacancy-serp__vacancy-title"], [data-qa="bloko-header-2"] a,
  [data-qa="vacancy-company-name"], [data-qa="company-header-title-name"] a {
    color: #e6edf3 !important; }
  [data-qa="serp-item__title"] span:not(.metro-point),
  [data-qa="vacancy-serp__vacancy-title"] span:not(.metro-point),
  [data-qa="vacancy-company-name"] span:not(.metro-point) {
    color: #e6edf3 !important; }
  [data-qa="serp-item__title"]:hover, [data-qa="vacancy-serp__vacancy-title"]:hover {
    color: #5fb0e6 !important; }

  /* ---- Search block (home + supernova + SERP) ---- */
  .supernova-search, [data-qa="supernova-search"], .HH-SupernovaSearch,
  [data-qa="search-input"], [class*="magritte-input"], input, textarea, select,
  [data-qa="vacancysearch__keywords-input"], [data-qa="advanced-search"] {
    background-color: #1c2128 !important; color: #e6edf3 !important;
    border-color: #2d333b !important; }
  /* hh paints the typed value with -webkit-text-fill-color (black), which
     overrides `color` → text reads black on the dark field. Repaint the fill on
     the real form controls only (NOT the input WRAPPERS, whose fill would also
     recolour the floating placeholder labels). */
  input, textarea { -webkit-text-fill-color: #e6edf3 !important; }
  /* Magritte text fields layer the <input> ON TOP of a floating <label> that
     acts as the placeholder (e.g. the hero "Номер телефона" phone CTA, the
     global search box, the salary / "Исключить слова" filters). Painting an
     OPAQUE bg on that input hides the label behind it — so keep the input
     element transparent and let its shell carry the dark surface. The value
     stays bright; the floating label + value-ghost become a muted placeholder. */
  input[class*="magritte-field"], textarea[class*="magritte-field"] {
    background-color: transparent !important; color: #e6edf3 !important; }
  [class*="magritte-content-container"], [class*="magritte-hint-container"] {
    background-color: #1c2128 !important; }
  /* The text field's OUTER layout wrapper is a div carrying `magritte-input___`;
     natively it is transparent, and the rounded shell is the inner
     `magritte-position-container`. Painting the wrapper draws a SQUARE slab that
     extends below the field, boxing the helper / validation-error row in an
     off-shape panel. Keep the wrapper bare — the real <input> elements are still
     covered by the `input, textarea, select` arm above. */
  div[class*="magritte-input___"] { background-color: transparent !important; }
  label[class*="magritte-label"], [class*="magritte-value-ghost"] {
    color: #8b949e !important; }
  input::placeholder, textarea::placeholder,
  [class*="magritte-input"] ::placeholder, .magritte-input___Vul7O ::placeholder {
    color: #8b949e !important; -webkit-text-fill-color: #8b949e !important; opacity: 1 !important; }
  /* the home page big segmented search wrapper */
  [data-qa="userTypeSegmented"] {
    background-color: transparent !important; }
  [data-qa="userTypeSegmentedApplicant"], [data-qa="userTypeSegmentedEmployer"] {
    color: #e6edf3 !important; }

  /* ---- Buttons ---- */
  .bloko-button, [class*="magritte-button"], button[class*="button"],
  [data-qa="search-button"], [data-qa="signup"], [data-qa="login"] {
    border-color: #2d333b !important; }
  /* secondary / tertiary buttons → dark surface */
  [class*="magritte-button-style-secondary"],
  [class*="magritte-button-style-tertiary"],
  .bloko-button_kind-default, .bloko-button:not([class*="primary"]) {
    background-color: #21262d !important; color: #e6edf3 !important; }
  [class*="magritte-button-style-secondary"]:hover,
  .bloko-button_kind-default:hover { background-color: #2d333b !important; }
  /* carousel scroll arrows ("Компании для вас" / recommendation rails) render as
     a round Magritte "secondary background" surface (magritte-background-style-
     secondary___) that the version-suffixed token remap misses → a bright white
     40px circle on the dark SERP. It's audit-blind (small control slips the
     surface-scan size floor). Dark the neutral secondary surface to the elevated
     card colour; its chevron already maps to #8b949e and reads on top. */
  [class*="magritte-background-style-secondary"] {
    background-color: #21262d !important; }
  /* primary CTA → hh blue accent, kept vivid. NB: don't paint the <button>
     element of the current Magritte component — its rounded surface is the
     inner `-view` span (fed by the accent token), so a bg here would leak a
     square blue slab past the rounded corners. */
  [class*="magritte-button-style-primary"], .bloko-button_kind-primary {
    background-color: #2f81f7 !important; color: #ffffff !important;
    border-color: #2f81f7 !important; }
  [class*="magritte-button-style-primary"]:hover,
  .bloko-button_kind-primary:hover { background-color: #4c9bff !important; }
  /* Current Magritte button: the visible surface moved onto an inner
     `magritte-button-view` span fed by the component tokens above, and the
     variant classes were renamed (`magritte-button_mode-*` +
     `magritte-button_style-*`). The label/icon colour must follow the variant —
     our blanket `span` / `a span` typography rules would otherwise paint the
     white label of a blue CTA light-grey (and every link-button blue). */
  [class*="magritte-button_style-accent"][class*="magritte-button_mode-primary"] span,
  [class*="magritte-button_style-special"][class*="magritte-button_mode-primary"] span,
  [class*="magritte-button_style-positive"][class*="magritte-button_mode-primary"] span,
  [class*="magritte-button_style-negative"][class*="magritte-button_mode-primary"] span {
    color: #ffffff !important; }
  /* `:not(.metro-point)` here is a specificity brace, not a filter: an anchor-
     button's label must outrank the link rule's `a span:not(.metro-point)` or a
     neutral CTA reads link-blue instead of primary text. */
  [class*="magritte-button_style-neutral"] span:not(.metro-point) {
    color: #e6edf3 !important; }
  [class*="magritte-button_style-accent"][class*="magritte-button_mode-secondary"] span,
  [class*="magritte-button_style-accent"][class*="magritte-button_mode-tertiary"] span {
    color: #5fb0e6 !important; }
  /* "constant" / "inverse" buttons live on hh's own always-black surfaces (the
     region-confirm tooltip, image overlays): their primary variant is a WHITE
     pill that must keep dark text, while their secondary/tertiary variants sit
     on #303030 and keep white text. Our blanket `span` colour would paint the
     white pill's label light-on-white. */
  [class*="magritte-button_style-constant"][class*="magritte-button_mode-primary"] span {
    color: #111111 !important; }
  [class*="magritte-button_style-inverse"][class*="magritte-button_mode-primary"] span {
    color: #0d1115 !important; }
  [class*="magritte-button_style-constant"][class*="magritte-button_mode-secondary"] span,
  [class*="magritte-button_style-constant"][class*="magritte-button_mode-tertiary"] span {
    color: #ffffff !important; }

  /* ---- Chips / filters / tags (search sidebar & SERP) ---- */
  [data-qa="chip"], [class*="magritte-chips"], [class*="magritte-chip"],
  [class*="bloko-tag"], [data-qa="serp__novafilter"], .novafilters,
  [class*="magritte-checkable-chips"] {
    background-color: #21262d !important; color: #c4cdd6 !important;
    border-color: #2d333b !important; }
  [class*="magritte-chips"][class*="checked"],
  [class*="magritte-chip"][class*="checked"] {
    background-color: #1f3550 !important; color: #e6edf3 !important; }
  [data-qa="advanced-filter"], [data-qa="serp__settings"],
  [data-qa="order-by-menu"], .supernova-filters {
    background-color: transparent !important; color: #c4cdd6 !important; }
  /* the SERP "add filter" chips (+ Район / Метро / График / Опыт …) darken at
     the button level, but their inner content span (magritte-content___) ships
     a hardcoded WHITE fill on TOP → light-on-light, unreadable. It's audit-blind
     (32px tall, under the surface-scan floor). Clear the inner fill so the dark
     chip button shows through; the label already maps to light grey, and the
     checked chip keeps its blue button surface. */
  [class*="magritte-chip"] [class*="magritte-content___"],
  [data-qa="chip"] [class*="magritte-content___"] {
    background-color: transparent !important; }
  /* …but the RADIO chips in the mobile "Фильтры" sheet (Сортировка, Время
     публикации, Искать только) are the opposite shape: the <label> is natively
     transparent and that SAME inner `magritte-content___` span IS the pill —
     #f1f4f9 unchecked vs a solid #000 + white label when checked. The rule above
     clears both, so every chip rendered as one identical grey slab and the sheet
     showed no current sort, no current period, nothing selected. State lives on a
     sibling `input:checked`, never on a class, so `[class*="checked"]` above
     matches nothing here and no DOM colour scan can see the loss.
     Re-establish both states on the span. `>` from the label lifts the resting
     arm to 0-2-1 to clear the transparent rule; the `:checked` arm follows it.
     Both arms stay anchored on `label[class*="magritte-chip___"] >`: the
     `input:checked + content` shape alone also matches the selectable role CARD
     on /account/login, which would flood it accent-blue. */
  label[class*="magritte-chip___"] > [class*="magritte-content___"] {
    background-color: #21262d !important; }
  label[class*="magritte-chip___"] > input:checked + [class*="magritte-content___"] {
    background-color: #2f81f7 !important; }
  label[class*="magritte-chip___"] > input:checked + [class*="magritte-content___"] [class*="magritte-text"] {
    color: #ffffff !important; }
  /* On the SERP, once you scroll the filter-chip bar re-mounts as a FIXED
     glass strip (CSS-module `sticky--<hash>`) with a hardcoded near-white
     `color(srgb 1 1 1 / 0.68)` background + backdrop blur — a white band under
     the dark chips. Absent at scroll 0 (evades top-of-page scans) and the
     hashed class + srgb() make it audit-blind. Pin it to the page base so the
     stuck bar matches the SERP behind it. */
  div[class*="sticky--"] {
    background-color: #14181d !important; }
  /* The EMPLOYER page's "Вакансии" tab runs the same stuck filter bar through a
     DIFFERENT CSS module, whose stuck state is `root--<hash> root-transparent--<hash>`
     — and despite the name it is `rgba(255,255,255,.8)`, so a bright grey band
     spans the full width behind the dark chips. Same class of miss as the SERP
     bar above: it is in flow and transparent at scroll 0, so nothing sees it
     until you scroll. Match on `root-transparent--` only — a bare `root--` is a
     generic CSS-module name that would hit unrelated component roots. */
  div[class*="root-transparent--"] {
    background-color: #14181d !important; }

  /* ---- Magritte tags: each style variant carries meaning ----
     A tag is not a card, but our card rule used to paint every `magritte-tag`
     the card colour: a neutral tag (#f1f4f9 natively) then matched the card it
     sat on and vanished, and a POSITIVE tag ("Отклик без резюме", green on pale
     green) came out as ordinary grey body text — indistinguishable from the
     "Опыт 1-3 года" chip beside it. Give each variant its own tinted surface and
     keep its label hue. */
  [class*="magritte-tag_style-neutral"] {
    background-color: #21262d !important; }
  [class*="magritte-tag_style-neutral"] [class*="magritte-tag__label"] {
    color: #c4cdd6 !important; }
  [class*="magritte-tag_style-positive"] {
    background-color: #16301f !important; }
  [class*="magritte-tag_style-positive"] [class*="magritte-tag__label"] {
    color: #57d98a !important; }
  [class*="magritte-tag_style-negative"] {
    background-color: #3a231e !important; }
  [class*="magritte-tag_style-negative"] [class*="magritte-tag__label"] {
    color: #ff8a7a !important; }
  [class*="magritte-tag_style-warning"] {
    background-color: #33261a !important; }
  [class*="magritte-tag_style-warning"] [class*="magritte-tag__label"] {
    color: #fdb972 !important; }
  [class*="magritte-tag_style-accent"] {
    background-color: #1f3550 !important; }
  [class*="magritte-tag_style-accent"] [class*="magritte-tag__label"] {
    color: #7cc3f0 !important; }
  [class*="magritte-tag_style-special"] {
    background-color: #241d33 !important; }
  [class*="magritte-tag_style-special"] [class*="magritte-tag__label"] {
    color: #c3a6f5 !important; }

  /* ---- Semantic text ----
     `magritte-text_style-<style>` is how Magritte marks a coloured label: the
     "Популярное сейчас" eyebrow on /services is purple (#9054ea), and the
     positive/negative/warning variants carry status. Our blanket typography
     rules greyed all of them. Keep each hue, lifted for a dark surface. */
  [class*="magritte-text"][class*="_style-special"] { color: #c3a6f5 !important; }
  [class*="magritte-text"][class*="_style-positive"] { color: #57d98a !important; }
  [class*="magritte-text"][class*="_style-negative"] { color: #ff8a7a !important; }
  [class*="magritte-text"][class*="_style-warning"] { color: #fdb972 !important; }
  [class*="magritte-text"][class*="_style-accent"] { color: #5fb0e6 !important; }

  /* ---- Semantic icons ----
     Magritte paints a meaning-bearing icon with `magritte-icon_initial-<style>`,
     and the muted-text rule above matches any class containing "secondary" — so
     `magritte-icon_initial-warning-secondary`, the GOLD employer-rating star,
     came out the same grey as a caption. Restore each semantic hue; a plain
     `magritte-icon_initial-secondary` is genuinely neutral and stays grey. */
  svg[class*="magritte-icon_initial-warning"] { color: #fdb972 !important; }
  svg[class*="magritte-icon_initial-positive"] { color: #57d98a !important; }
  svg[class*="magritte-icon_initial-negative"] { color: #ff8a7a !important; }
  svg[class*="magritte-icon_initial-accent"] { color: #5fb0e6 !important; }

  /* ---- Filter select / "trigger" controls (sidebar dropdowns: schedule,
     working hours, payout period, etc. — shipped white) ---- */
  [class*="magritte-trigger"], [data-qa="magritte-select-activator"],
  [data-qa="trigger-root"], [data-qa^="filter-select-trigger"] {
    background-color: #1c2128 !important; color: #e6edf3 !important;
    border-color: #2d333b !important; }
  /* the open select / dropdown menu surface (portaled, must stay opaque dark;
     skip the invisible base/container/border wrappers) */
  [class*="magritte-drop___"], [class*="magritte-select-drop"],
  [class*="magritte-menu"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  /* Magritte modals/dialogs (newer component versions paint a hardcoded WHITE
     panel the token remap misses — e.g. the ccTLD "Выберите язык" language
     picker on hh.kz/uz/by). Keep them opaque dark + lift their close glyph. */
  [class*="magritte-modal"], [role="dialog"][class*="magritte"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [class*="magritte-modal"] [class*="magritte-modal-close"] svg,
  [class*="magritte-modal"] [class*="magritte-modal-close"] svg path {
    color: #c4cdd6 !important; fill: currentColor !important; }
  /* At 390px the login/signup flow opens as a FULL-SCREEN overlay whose backing
     layer (a CSS-module `container--<hash> animated--<hash>`, position:fixed,
     z-index 1000, the whole viewport) ships a hardcoded WHITE surface. The dark
     Magritte card inside is inset ~16px, so the white reads as a bright frame
     around the card on every edge — and it is exposed outright while the
     `animated--` open transition runs. Desktop never renders it (the flow is a
     centred page there), so a desktop-only pass misses it entirely. Both hashed
     module prefixes are required, which matches this overlay and nothing else. */
  div[class*="container--"][class*="animated--"] {
    background-color: #14181d !important; }
  /* the ccTLD "Выберите язык" language picker (hh.kz/uz/by) was redesigned onto the
     Magritte "nav-bar-panes" component: its close button ships a light-glass
     (rgba(255,255,255,.68)) rounded square with a BLACK X glyph — a bright control
     on the dark modal, and the pane's own "-pane-background" backing layer is a
     hardcoded white. Both are audit-blind-ish (the backing is occluded, the glass
     square is a small control). Dark the glass + backing and lift the glyph. */
  [class*="magritte-pane-background"] {
    background-color: #1c2128 !important; }
  /* the mobile bottom-sheet's sticky header (the "Фильтры" title bar on the SERP
     filter sheet) is a `magritte-background-container` painted hardcoded WHITE —
     a bright strip across the top of an otherwise dark sheet, with our light title
     text on it, unreadable. Only exists while the sheet is open, so no load-time
     scan reaches it. */
  [class*="magritte-background-container"] {
    background-color: #1c2128 !important; }
  [data-qa="select-modal-close"] [class*="magritte-view"] {
    background-color: #21262d !important; }
  [data-qa="select-modal-close"] svg,
  [data-qa="select-modal-close"] svg path {
    color: #c4cdd6 !important; fill: #c4cdd6 !important; }

  /* ---- Auth form: phone calling-code box + neutral "show more" social
     aggregator ship WHITE (the aggregator's hh label is light-grey → unreadable
     on white). Dark them; individual OAuth buttons keep their brand white. ---- */
  [data-qa="magritte-phone-input-calling-code"],
  [class*="magritte-calling-code-input-container"],
  [data-qa="account-login-social-show-more"] {
    background-color: #21262d !important; border-color: #2d333b !important;
    color: #e6edf3 !important; }
  [data-qa="account-login-social-show-more"] span,
  [data-qa="magritte-phone-input-calling-code"] span {
    color: #e6edf3 !important; }
  /* the OAuth provider tiles (Sber ID / VK / …) are "inverse" buttons: their
     glyph is painted with the near-black inverse token and their tile is dark
     under this theme → dark-on-dark. The glyphs use fill="currentColor", so
     lifting `color` alone recolours them without flattening any brand logo
     that ships an explicit fill. */
  [class*="magritte-branded-button"] svg {
    color: #e6edf3 !important; }

  /* ---- Checkboxes / radios: keep checked accent visible ---- */
  [data-qa="checkbox"], [class*="magritte-checkbox"], [class*="magritte-radio"] {
    border-color: #3a424c !important; }
  /* the actual control disc (magritte-radio___ / magritte-checkbox___ — the
     hash-suffixed leaf, ~20px) ships a WHITE unchecked fill. It's audit-blind:
     the surface scan needs >120×40 so a 20px control slips past. Dark the
     unchecked disc to the card surface (its #3a424c border reads as an empty
     ring); the checked disc keeps the accent fill. */
  [class*="magritte-radio___"], [class*="magritte-checkbox___"] {
    background-color: #1c2128 !important; }
  input:checked + [class*="magritte-radio___"],
  input:checked + [class*="magritte-checkbox___"] {
    background-color: #2f81f7 !important; }

  /* ---- Form validation: keep the error signal ----
     The helper row under a Magritte field (`Обязательное поле`) is the site's
     error signal, painted with the negative token (#ff4d3a). Our blanket
     typography rules collapsed it to ordinary body grey, so a rejected field
     read like a caption — the red focus ring was the only cue left. Restore the
     site's own red; it clears 4.5:1 on both the page base and the card. */
  [class*="magritte-form-helper-error"],
  [class*="magritte-form-helper-error"] [class*="magritte-text"],
  [class*="magritte-form-helper-error"] [class*="magritte-form-helper-text-wrapper"] {
    color: #ff4d3a !important; }

  /* ---- Salary / compensation: keep its meaning, stay readable ---- */
  [data-qa="vacancy-serp__compensation"], [data-qa="vacancy-serp__vacancy-compensation"],
  [data-qa="vacancy-salary"], [class*="compensation"] {
    color: #d6dde3 !important; }

  /* ---- Vacancy detail page ---- */
  [class*="magritte-content-border-container"], .vacancy-section {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [data-qa="vacancy-title"], [data-qa="vacancy-description"],
  [class*="vacancy-branded"], .bloko-tag-list,
  [data-qa="vacancy-view-employment-mode"] {
    color: #c4cdd6 !important; }
  [data-qa="vacancy-description"] * { color: inherit !important; }
  /* Branded ("chameleon") vacancy descriptions inject the employer's OWN
     stylesheet, which highlights section headers with a bright fill on inline
     tags (e.g. a #58ffff cyan <strong> "ОБЯЗАННОСТИ:"). The fill comes from the
     employer rule (not inline) so a white-surface scan misses it, and our forced
     light body text then reads light-on-bright — effectively invisible. Neutralise
     those inline highlight fills within branded user content so the bold header
     reads as clean light text on the dark card (text is already forced light, so
     no dark-on-dark). NB: employer-authored TEXT colours are deliberately NOT
     preserved — the `color: inherit` rule above flattens them, because employer
     CSS is unbounded and a hardcoded near-black heading would otherwise land
     dark-on-dark. audit-chroma reports these as `flattened`; that is intended. */
  [class*="vacancy-branded-user-content"] strong,
  [class*="vacancy-branded-user-content"] b,
  [class*="vacancy-branded-user-content"] em,
  [class*="vacancy-branded-user-content"] font,
  [class*="vacancy-branded-user-content"] span {
    background-color: transparent !important; }
  /* search-term highlight: keep the "matched word" meaning, dark amber */
  span.highlighted, mark, .bloko-text_highlighted {
    background-color: #4a3a12 !important; color: #f0d58a !important; }

  /* ---- Employer / company page ---- */
  [data-qa="employer-chameleon-header"], [class*="employer-header"],
  [data-qa="company-header-title"], .employer-sidebar, .employer-info {
    background-color: transparent !important; }
  [data-qa="company-header-title-name"], [data-qa="company-header-title"] {
    color: #e6edf3 !important; }
  [data-qa="employer-page-description"], .employer-description,
  [class*="employer-page"] { color: #c4cdd6 !important; }
  /* company logo: never tint the image */
  [data-qa="company-logo-image"], [data-qa="company-logo-image"] img,
  [class*="company-logo"] img { background-color: transparent !important; }

  /* ---- Ratings / reviews stars: keep them visible (preserve semantic) ---- */
  [data-qa="employer-reviews-stars"], [data-qa="employer-review-small-widget-total-rating"],
  [class*="rating-stars"] { color: inherit; }

  /* ---- Tabs ---- */
  [data-qa="tab-list"], [class*="magritte-tab"], .bloko-tabs-item {
    background-color: transparent !important; border-color: #2d333b !important; }
  /* Magritte tabs are PILLS now: the current tab carries `magritte-tab_selected`
     and ships a solid dark pill + white label — not an `-active` class with a
     coloured border-bottom. The old `[class*="active"]` selectors matched
     nothing, so the blanket transparent background above erased the only
     "you are here" cue and both tabs rendered identically. */
  [class*="magritte-tab_selected"] {
    background-color: #30363d !important; }
  [class*="magritte-tab_selected"] [class*="magritte-tab-content"],
  [class*="magritte-tab_selected"] [class*="magritte-tab-label"] {
    color: #ffffff !important; }
  .bloko-tabs-item_active {
    color: #e6edf3 !important; border-bottom-color: #2f81f7 !important; }
  [class*="magritte-tab"]:not([class*="selected"]), .bloko-tabs-item:not(.bloko-tabs-item_active) {
    color: #c4cdd6 !important; }
  /* A tab's LABEL is a `magritte-text_style-primary` span whichever state the tab
     is in — the component, not the class, carries the state (selected #fff /
     unselected #6a7885). Our heading rule matches `magritte-text` + `primary` and
     painted BOTH the same #e6edf3, so on the search tab bar "Резюме" and
     "Компании" read exactly as bright as the current "Вакансии": only the pill
     was left to say where you are. Mute the unselected label.
     Anchored on `magritte-tab___` (triple underscore = the tab button itself):
     a bare `magritte-tab` prefix would also match the inner `magritte-tab-content`
     wrapper, which carries no state class, so the SELECTED label would match too
     and every tab would grey out. */
  [class*="magritte-tab___"]:not([class*="selected"]) [class*="magritte-tab-label"],
  [class*="magritte-tab___"]:not([class*="selected"]) [class*="magritte-tab-label"] [class*="magritte-text"] {
    color: #8b949e !important; }

  /* ---- Tables (within descriptions) ---- */
  table { background-color: transparent !important; }
  th { background-color: #1c2128 !important; color: #e6edf3 !important; }
  td, th { border-color: #2d333b !important; color: #c4cdd6 !important; }

  /* ---- Login / auth page ---- */
  /* the full-page auth backdrop is a decorative illustration baked on WHITE
     (a background-IMAGE — invisible to a bg-color scan, and `lightBgImages` only
     flags gradients, so audit-theme returns total=0 on a fully white login page);
     drop it so the dark base shows behind the centred sign-in card.
     Both spellings ship: the CSS-module wrapper is `wrapper-with-image--<hash>`,
     which does NOT contain the older `wrapper-image` substring. */
  [class*="wrapper-image"], [class*="wrapper-with-image"],
  [class*="account-login-page"] {
    background-image: none !important; background-color: #14181d !important; }
  /* the mobile standalone auth layout wraps the whole page in a full-viewport
     "light-page" div (hardcoded #f4f6fb). It sits BEHIND the dark auth overlay so
     it is normally occluded, but the same overlay has a history of white-frame
     bleed at the open transition — dark this backing wrapper to the page base so
     nothing light can show through an edge (its dark siblings re-set harmlessly). */
  [class*="light-page"] {
    background-color: #14181d !important; }
  /* the small "mode-icon" avatars (employer info badges: location /
     registration) ship a black glyph on a light neutral disc — darken the disc
     and lift the glyph (its fill is currentColor, which resolves to black) so
     the icon stays legible on the dark card */
  [class*="magritte-avatar_mode-icon"][class*="magritte-avatar_style-secondary"] {
    background-color: #21262d !important; }
  [class*="magritte-avatar_mode-icon"][class*="magritte-avatar_style-secondary"] svg,
  [class*="magritte-avatar_mode-icon"][class*="magritte-avatar_style-secondary"] svg path {
    color: #b8c0c9 !important; fill: currentColor !important; }
  /* the ACCENT variant of those mode-icon discs (e.g. the employer "Сайт"
     website-link badge) ships a pale-blue disc — dark it to a blue-tinted
     surface; its accent-blue glyph stays its brand colour and reads on top. */
  [class*="magritte-avatar_mode-icon"][class*="magritte-avatar_style-accent-secondary"] {
    background-color: #1f3550 !important; }
  /* the "IT-аккредитация" employer chip (a ~24px disc next to the rating, and on
     vacancy / search cards) ships a light disc with a BLACK currentColor "it"
     glyph. It's audit-blind — the surface scan needs >120×40 so the small disc
     slips past — and reads as a bright spot on dark. Dark the disc to the card
     surface and lift its glyph (its fill is currentColor). */
  [data-qa="accredited-it-employer-icon"] {
    background-color: #21262d !important; }
  [data-qa="accredited-it-employer-icon"] svg,
  [data-qa="accredited-it-employer-icon"] svg path {
    color: #b8c0c9 !important; fill: currentColor !important; }

  /* ---- Cookie / consent informer (kill the bright bar; click-dismiss in real use) ---- */
  [data-qa="cookies-policy-informer"], .cookies-policy-informer {
    background-color: #0d1117 !important; border-color: #2d333b !important; color: #c4cdd6 !important; }
  /* legacy Bloko notification toast (the mobile "Ваш регион — Москва?" region
     prompt, and other transient bloko notices) ships a hardcoded WHITE
     `bloko-notification__plate`. Desktop uses the native-dark magritte tooltip, so
     this only surfaces on the mobile/legacy path — a bright banner over the dark
     SERP. Dark the plate; its title maps to light via the typography rules, its
     accent buttons stay blue and the info glyph keeps its accent hue. */
  [class*="bloko-notification__plate"], [class*="bloko-notification__wrapper"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }

  /* ---- Footer ---- */
  [class*="footer-nav"], [class*="footer-app-banner"], .supernova-footer,
  footer, .footer, [data-qa="footer"] {
    background-color: #0d1117 !important; border-color: #2d333b !important; }
  [class*="footer-nav"] a, .supernova-footer a, footer a { color: #8ab4d8 !important; }
  [class*="footer-nav"] span, footer span, .copyright { color: #8b949e !important; }

  /* ---- Banners / ad surrounds: dark, no bright leaks (don't theme iframe content) ---- */
  [class*="banner-place"], [class*="footer-app-banner-redesign"], .HH-Banners {
    background-color: #14181d !important; border-color: #2d333b !important; }
  /* App-download QR codes (the footer "Мобильное приложение" block and the
     footer app banner) are transparent images of BLACK modules — natively they
     sit on hh's white page. Once the surrounding surface goes dark the modules
     are black-on-dark: invisible to the eye and unreadable to a scanner, while
     every audit passes (the element's own background-color IS our dark value, and
     the module art is raster/SVG paint). A QR needs a light quiet zone to scan, so
     give these two containers a white backing. NB: the "Вакансии в мессенджере"
     card's QR is a .webp with white already baked in and needs nothing. */
  [class*="footer-app-banner-redesign-qr-image"], [class*="qr-code--"] {
    background-color: #ffffff !important; }
  /* Both QR blocks now nest the code inside a Magritte CARD, and the generic card
     rule paints that card #21262d — an opaque dark tile laid ON TOP of the white
     backing above, so the black modules render on dark grey and the code cannot be
     scanned at all. Every audit still passes: the `qr-code--` element's own
     background-color IS #ffffff, the card is a legitimately-dark card, and the
     modules are image paint. Give the card the same white quiet zone. The card
     holds nothing but the code (the "Мобильное приложение" caption and the app-
     banner copy are siblings, outside it), so no text lands on the white.
     `-qr--` keeps the app-banner arm to the base wrapper — the sibling
     `-qr-image--` never contains the double dash. */
  [class*="qr-code--"] [class*="magritte-card"],
  [class*="footer-app-banner-redesign-qr--"] [class*="magritte-card"] {
    background-color: #ffffff !important; }

  /* ---- "Vacancies on map" button (shipped light) ---- */
  [class*="map-button"] {
    background-color: #21262d !important; border-color: #2d333b !important; }
  /* the label rides a translucent white glass pill (rgba(255,255,255,.68) +
     backdrop-blur) laid over the map preview — audit-blind (exactly 40px tall,
     so it slips the surface-scan floor) and our light label then reads
     light-on-light. Flip the glass dark; the label stays bright. */
  [class*="map-button"] [class*="button--"] {
    background-color: rgba(13, 17, 23, 0.72) !important; }
  /* vacancy detail "Где предстоит работать" Yandex map: the raster tiles sit on
     a WHITE map-bg pane (and the container itself is light) — when tiles are
     slow/partial that pane glares white. Dark the container + ymaps base pane so
     any uncovered area reads dark; the opaque tiles still paint over it. */
  .vacancy-address-map, [class*="vacancy-address-map"],
  [class*="ymaps"][class*="-map-bg"], [class*="ymaps"][class*="-ground-pane"] {
    background-color: #1c2128 !important; }

  /* ---- Pagination / "show more" controls ----
     Natively only the CURRENT page carries a filled pill; the wrapper and the
     other page links are bare. Painting the whole component one grey turned the
     pager into a row of identical chips and erased the "you are here" cue.
     Keep the links bare and give the selected page its own pill. */
  [class*="magritte-number-pages-wrapper"],
  [class*="magritte-number-pages-container"],
  [class*="magritte-number-pages-item"],
  [class*="magritte-number-pages-ellipsis"],
  [class*="magritte-number-pages-action"] {
    background-color: transparent !important; color: #c4cdd6 !important; }
  [data-qa^="pager-"] {
    background-color: transparent !important; color: #c4cdd6 !important; }
  [class*="magritte-number-pages-action"]:hover {
    background-color: #21262d !important; }
  [class*="magritte-number-pages-action"][class*="selected"] {
    background-color: #30363d !important; color: #ffffff !important; }

  /* ---- Sticky bottom action bar (vacancy detail "Откликнуться" bar) ----
     it ships a hardcoded WHITE surface and only becomes position:fixed once you
     scroll, so a top-of-page scan never sees it. Dark the floating bar; the
     buttons inside already map to dark/accent. */
  [class*="magritte-action-bar"] {
    background-color: #0d1117 !important; border-color: #2d333b !important; }

  /* the /services hub "Популярное сейчас" section ships a hardcoded light-lavender
     (#f7f4ff) full-width wrapper behind the dark service cards — a bright band the
     token remap misses (it's a raw hex, not a magritte var). Dark it to the page
     base so the cards read as elevated surfaces on top. */
  [class*="popular-services-wrapper"] {
    background-color: #14181d !important; }

  /* ---- Blog / articles (/articles hub + /article/<id> CMS body) ----
     (1) the "cms-aside" pull-quote callout and the "cms-album" image placeholders
     ship a hardcoded light #f9f9f9 panel — a bright box on the dark article. The
     aside's own label is a dark #333 carried on a tag our typography rules never
     match (so it would go dark-on-dark once the panel is darkened). Dark the
     surface and force its text light. */
  [class*="cms-aside"], [class*="cms-album__placeholder"], [class*="cms-album__frame"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [class*="cms-aside"], [class*="cms-aside"] * { color: #c4cdd6 !important; }
  /* (2) the blog category chips (`tag--<hash>` + a `tag-<colour>--<hash>` modifier)
     ship a PALE tint (#fdede9 red … #f4f6fb grey) with NO text colour of their own —
     the label inherits dark body text natively, which our blanket div rule flattened
     to light grey → light-on-pale, barely legible. Dark each colour to a tinted
     surface and lift its label so the category colour coding survives (both classes
     are required, so this matches ONLY the blog pills, never a magritte/bloko tag). */
  [class*="tag--"][class*="tag-red--"] { background-color: #3a231e !important; }
  [class*="tag--"][class*="tag-red--"], [class*="tag--"][class*="tag-red--"] * { color: #ff8a7a !important; }
  [class*="tag--"][class*="tag-orange--"] { background-color: #33261a !important; }
  [class*="tag--"][class*="tag-orange--"], [class*="tag--"][class*="tag-orange--"] * { color: #fdb972 !important; }
  [class*="tag--"][class*="tag-yellow--"] { background-color: #33261a !important; }
  [class*="tag--"][class*="tag-yellow--"], [class*="tag--"][class*="tag-yellow--"] * { color: #e6c766 !important; }
  [class*="tag--"][class*="tag-green--"] { background-color: #16301f !important; }
  [class*="tag--"][class*="tag-green--"], [class*="tag--"][class*="tag-green--"] * { color: #57d98a !important; }
  [class*="tag--"][class*="tag-blue--"] { background-color: #1f3550 !important; }
  [class*="tag--"][class*="tag-blue--"], [class*="tag--"][class*="tag-blue--"] * { color: #7cc3f0 !important; }
  [class*="tag--"][class*="tag-violet--"] { background-color: #241d33 !important; }
  [class*="tag--"][class*="tag-violet--"], [class*="tag--"][class*="tag-violet--"] * { color: #c3a6f5 !important; }
  [class*="tag--"][class*="tag-grey--"] { background-color: #21262d !important; }
  [class*="tag--"][class*="tag-grey--"], [class*="tag--"][class*="tag-grey--"] * { color: #c4cdd6 !important; }

  /* ---- Misc surfaces hh paints white directly ---- */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background:#fff"], [style*="background: #fff"],
  [style*="background-color:#fff"] { background-color: #1c2128 !important; }
  /* legacy near-black text hardcoded inline (#1b1b1b / #2a3137 / #000) */
  [style*="color: rgb(27, 27, 27)"], [style*="color: rgb(42, 49, 55)"],
  [style*="color: rgb(0, 0, 0)"], [style*="color:#000"] { color: #c4cdd6 !important; }

  hr { border-color: #2d333b !important; }
  ::selection { background-color: #2f6fb8 !important; color: #ffffff !important; }
}
